from pwn import *
import struct

# Helper function to decode VM instructions
def decode_instruction(data):
    return struct.unpack("<QQQQ", data[:32])

def analyze_vm():
    elf = ELF('./ctf_files/prog')

    # Extract VM bytecode from binary
    vm_code_offset = 0x80487e0
    vm_code_size = elf.read(0x8048000, 4)
    vm_code = elf.read(vm_code_offset, struct.unpack("<I", vm_code_size)[0])

    print("[*] Analyzing VM Instructions")
    print("=" * 50)

    # Create instruction map
    instructions = []
    for i in range(0, len(vm_code), 32):
        if i + 32 > len(vm_code):
            break

        opcode, arg1, arg2, arg3 = decode_instruction(vm_code[i:i+32])

        inst_type = ""
        if opcode & 1:  # First group
            if opcode & 2:
                inst_type = "MOV_IMM"
            else:
                inst_type = "MOV_REG"
        elif opcode & 0x10:  # Second group
            if opcode & 0x20:
                inst_type = "ARITHMETIC_IMM"
            else:
                inst_type = "ARITHMETIC_REG"
        elif opcode & 0x100:  # Third group
            if opcode & 0x200:
                inst_type = "LOGIC_IMM"
            else:
                inst_type = "LOGIC_REG"
        elif opcode & 0x1000:  # Fourth group
            if opcode & 0x2000:
                inst_type = "SHIFT_IMM"
            else:
                inst_type = "SHIFT_REG"
        elif opcode & 0x10000:  # Fifth group
            if opcode & 0x20000:
                inst_type = "MEM_IMM"
            elif opcode & 0x40000:
                inst_type = "MEM_SWAP"
            elif opcode & 0x80000:
                inst_type = "MEM_COPY"
            else:
                inst_type = "MEM_REG"
        elif opcode & 0x100000:  # Input/Output
            inst_type = "IO_OPERATION"
        elif opcode & 0x1000000:  # System related
            inst_type = "SYS_CALL"
        elif opcode & 0x10000000:  # Control flow
            if opcode & 0x20000000:
                inst_type = "JMP"
            else:
                inst_type = "CMP"

        instructions.append({
            'offset': i,
            'opcode': opcode,
            'args': (arg1, arg2, arg3),
            'type': inst_type
        })

        print(f"[+] Offset: {hex(i)}")
        print(f"    Type: {inst_type}")
        print(f"    Opcode: {hex(opcode)}")
        print(f"    Args: {hex(arg1)}, {hex(arg2)}, {hex(arg3)}")
        print()

    # Analyze potential vulnerabilities
    print("\n[*] Potential Vulnerabilities")
    print("=" * 50)

    for inst in instructions:
        # Check for dangerous memory operations
        if "MEM" in inst['type']:
            if inst['args'][0] > 0x1000 or inst['args'][1] > 0x1000:
                print(f"[!] Potential out-of-bounds memory access at offset {hex(inst['offset'])}")
                print(f"    Type: {inst['type']}")
                print(f"    Args: {[hex(x) for x in inst['args']]}")

        # Check for uncontrolled jumps
        if inst['type'] == "JMP":
            if inst['args'][0] > 0x1000:
                print(f"[!] Potentially dangerous jump at offset {hex(inst['offset'])}")
                print(f"    Target: {hex(inst['args'][0])}")

        # Check for syscall instructions
        if inst['type'] == "SYS_CALL":
            print(f"[!] System call found at offset {hex(inst['offset'])}")
            print(f"    Args: {[hex(x) for x in inst['args']]}")

analyze_vm()

